    Initialize: function(component, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var items = component.records;
        var aplTotSmamt = 0;


        var date =new Date();

        var mm = date.getMonth() +1;

        //그달의 07일 이전이면 이전 월 설정 아니면 현재 월 설정
        if (DateUtils.getDate(new Date()) < DateUtils.getDate(new Date()).substr(0, 6) + '07') {
            mm -= 1;
        }

        if(mm < 10){
            mm = "0"+ mm;
        } else {
            mm = mm.toString();
        }
        refs.dtpStDt.setValue(date.getFullYear()+'년 ' + mm +"월");


        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command   : Constants.sanction.DRAFT,
            viewModel : vm,
            edocCd    : vm.get('docCd'),
            scope     : me
        });




    },

